const hex=c=>[1,3,5].map(i=>parseInt(c.slice(i,i+2),16));
const toHex=a=>'#'+a.map(v=>Math.max(0,Math.min(255,Math.round(v))).toString(16).padStart(2,'0')).join('');
const mix=(c,t,a)=>{const x=hex(c),y=hex(t);return toHex(x.map((v,i)=>v+(y[i]-v)*a))};
const lum=c=>{const [r,g,b]=hex(c);return(0.299*r+0.587*g+0.114*b)/255};
function colorVars(st,c){st.setProperty('--k1',mix(c,'#ffffff',.28));st.setProperty('--k2',c);st.setProperty('--ke',mix(c,'#000000',.42));st.setProperty('--kt',lum(c)>.62?'#1a1a1a':'#fff')}
