function frameOf(c){return`linear-gradient(135deg,${mix(c,'#ffffff',.55)},${c} 35%,${mix(c,'#000000',.45)} 65%,${mix(c,'#ffffff',.25)})`}
function applyBoard(){const c=$('bcard'),b=save.bg,f=save.fr,w=save.fw||6;
 let fill='var(--panel)',dk=0;
 if(b&&b.c){fill=`linear-gradient(145deg,${mix(b.c,'#ffffff',.85)},${mix(b.c,'#ffffff',.55)})`}
 else if(b&&b.i!=null&&BGS[b.i]){fill=BGS[b.i][1];dk=BGS[b.i][2]}
 c.style.setProperty('--bgfill',fill);
 {let pc=null;if(b&&b.c)pc=b.c;else if(b&&b.i!=null&&BGS[b.i]){const m=/#[0-9a-fA-F]{6}/.exec(BGS[b.i][1]);if(m)pc=m[0]}document.body.classList.toggle('pgc',!!pc);if(pc)document.body.style.setProperty('--pgc',pc);else document.body.style.removeProperty('--pgc')}
 c.classList.toggle('dk',!!dk);
 let fr=null;if(f&&f.c)fr=frameOf(f.c);else if(f&&f.i>0&&FRS[f.i])fr=FRS[f.i][1];
 c.style.setProperty('--frame',fr||'none');c.style.setProperty('--fw',fr?w+'px':'0px');
 const g=f&&f.c?f.c:(f&&f.i>0?['','#e8b923','#000','#9aa1ad','#e7a08f','#2748c9','#1fa56e','var(--k2)'][f.i]:null);
 c.style.setProperty('--fglow',fr?`0 0 0 1px rgba(0,0,0,.15),0 0 22px -4px ${g},0 16px 34px -18px rgba(0,0,0,.5)`:'');
 document.querySelectorAll('#bgs button').forEach((x,i)=>x.classList.toggle('on',!!b&&!b.c&&b.i===i||(!b&&i===0)));
 document.querySelectorAll('#frs button').forEach((x,i)=>x.classList.toggle('on',!!f&&!f.c&&f.i===i||(!f&&i===0)));
 document.querySelectorAll('#frw button').forEach(x=>x.classList.toggle('on',+x.dataset.w===w))}
BGS.forEach(([n,css],i)=>{const b=h('button');b.title=n;b.setAttribute('aria-label',n);b.style.background=css;b.onclick=()=>{save.bg={i};persist();applyBoard()};$('bgs').append(b)});
FRS.forEach(([n,css],i)=>{const b=h('button');b.title=n;b.setAttribute('aria-label',n);b.style.background=i?css:'repeating-linear-gradient(45deg,#fff,#fff 5px,#e5e5e5 5px,#e5e5e5 10px)';b.onclick=()=>{save.fr={i};persist();applyBoard()};$('frs').append(b)});
$('bgc').oninput=e=>{save.bg={c:e.target.value};persist();applyBoard()};
$('frc').oninput=e=>{save.fr={c:e.target.value};persist();applyBoard()};
document.querySelectorAll('#frw button').forEach(x=>x.onclick=()=>{save.fw=+x.dataset.w;persist();applyBoard()});
if(save.bg&&save.bg.c)$('bgc').value=save.bg.c;if(save.fr&&save.fr.c)$('frc').value=save.fr.c;
applyBoard();
