 $('lg').innerHTML='<span><i class="tpl ga" style="padding:1px 10px">G9–10</i> Grades 9 &amp; 10</span><span><i class="tpl gb" style="padding:1px 10px">G11–12</i> Grades 11 &amp; 12</span><span>☕ Hatched columns = Breaks (with times)</span><span><i class="fleg">Friday</i> Friday (periods 1–4 only)</span>'+(RM?'<span>🌙 Ramadan 1447 schedule</span>':'');
 if(!L.length){bd.append(h('div','empty',F.t&&!cnt(F.t)?'No lessons are recorded for this teacher in the file.':'No lessons match the current filters.'));return}
 const useCls=$('cc').checked;const dw=h('div','days');bd.append(dw);
