   k.append(h('span','kc'+(!stu&&l.c.length>13&&l.s<2?' lg':''),stu?(l.k||l.c):l.c));if(l.k&&!stu)k.append(h('span','ks',l.k));
   if(stu){const dk=PRE[(String(l.k||'').match(/^[A-Z]+/)||[''])[0]];if(dk&&DN[dk])k.append(h('span','ks',DN[dk]))}
   if(!F.t)k.append(h('span','kn',l.t));
   if(l.r)k.append(h('span','kr',l.r));
   const tv=tm(l);if(tv)k.append(h('span','kt2',tv));
