const rng=(p,s)=>p+(s>1?'–'+(p+s-1):'');
function verdict(n,r){
 const d=dayIdx(r.date),sp=spanOf(r),tv=tm({c:r.cls||'',d,p:r.per,s:sp});
 if(n===r.absent)return{cls:'bad',msg:'⛔ Cannot assign — this is the absent teacher.'};
 if(absentOn(n,r.date,r))return{cls:'bad',msg:'⛔ Cannot assign — '+n+' is recorded absent on the same day.'};
 const c=conflictOf(n,r.date,d,r.per,sp,r);
 if(c){if(c.kind==='lesson'){const l=c.l;return{cls:'bad',msg:'⛔ Time conflict — '+n+' has a lesson at the same time: period '+rng(l.p,l.s)+' · '+l.c+(tm(l)?' · '+tm(l):'')+'. Lessons must not overlap.'}}
  return{cls:'bad',msg:'⛔ Time conflict — '+n+' is assigned as substitute at the same time (period '+rng(c.r.per,spanOf(c.r))+' · '+c.r.cls+' · for the absent teacher '+c.r.absent+').'}}
 const load=loadOf(n,r.date,d,r);
 if(!LD[n].length)return{cls:'warn',msg:'⚠ No timetable is recorded for this teacher in the file — check availability manually.'};
 if(load+sp>5)return{cls:'warn',msg:'⚠ Available at this time, but he will then have '+(load+sp)+' lessons today (more than 5).'};
 return{cls:'ok',msg:'✔ Available in period '+rng(r.per,sp)+(tv?' ('+tv+')':'')+' — he will then have '+(load+sp)+' lessons today.'}}
