/* ===== SUBSTITUTION ALERTS ===== */
(function(){
 const E=eds.find(e=>e.cfg.n==='sub'),key=r=>JSON.stringify([r.date,r.absent,r.per,r.subst,r.cls]);
 let prev=null,subUpd=0,db=null;const nb=()=>document.querySelector('.nb[data-view="sub"]');
 const nameHit=n=>{if(!MS.me)return false;const a=nrm(n),m=nrm(MS.me.name),e=nrm(MS.me.email),r=MS.roster.find(x=>nrm(x.email)&&nrm(x.email)===e);const cands=[m,r&&nrm(r.name)].filter(Boolean);return cands.some(c=>c&&a&&(c===a||(Math.min(c.length,a.length)>4&&(c.includes(a)||a.includes(c)))))};
 function glow(){const un=subUpd&&subUpd>(save.subSeen||0);const b=nb();if(b)b.classList.toggle('alert2',!!un);const v=$('v_sub');if(v)v.classList.toggle('lit',!!un)}
 const sv=showView;showView=function(id){sv(id);if(id==='sub'&&subUpd){save.subSeen=subUpd;persist();glow()}};
 function show(list){$('ntfL').innerHTML='';list.forEach(a=>$('ntfL').append(h('p','',a.text)));$('ntf').classList.add('on');try{ring('start')}catch(e){}
  try{if(window.Notification&&Notification.permission==='granted')new Notification('Substitution Schedule',{body:list[0].text})}catch(e){}}
 $('ntfX').onclick=()=>$('ntf').classList.remove('on');$('ntfGo').onclick=()=>{$('ntf').classList.remove('on');showView('sub')};
 addEventListener('pointerdown',()=>{try{if(window.Notification&&Notification.permission==='default')Notification.requestPermission()}catch(e){}},{once:true});
 (async function(){
  try{if(window.claude&&claude.use)db=await claude.use('db')}catch(e){}
  if(!db)return;
  db.doc('coord/sub').onSnapshot(s=>{const d=s.exists?s.data():null;const rows=d&&Array.isArray(d.rows)?d.rows:[];subUpd=d&&d.upd||0;
   if(prev===null&&!save.subSeen&&subUpd){save.subSeen=subUpd;persist()}
   prev=rows.map(r=>({...r}));glow()},()=>{});
  db.doc('coord/alerts').onSnapshot(s=>{const list=s.exists&&Array.isArray(s.data().list)?s.data().list:[];
   if(save.alSeen==null){save.alSeen=list.reduce((m,a)=>Math.max(m,a.ts||0),0);persist();return}
   const mine=list.filter(a=>a.ts>save.alSeen&&(a.names||[]).some(nameHit));
   save.alSeen=Math.max(save.alSeen,...list.map(a=>a.ts||0));persist();
   if(mine.length)show(mine)},()=>{});
 })();
 const old=$('s_sub').onclick;
 $('s_sub').onclick=async()=>{
  const before=prev?prev.map(key):[];await old();
  if(!db||E.dirty)return;
  const rows=E.rows.filter(r=>r.absent&&r.date),fresh=rows.filter(r=>!before.includes(key(r)));
  if(!fresh.length)return;
  const al=fresh.map(r=>({id:newId(),ts:Date.now(),names:[r.absent,r.subst].filter(Boolean),text:(r.subst?r.subst+' covers ':'Cover needed for ')+(r.per?'period '+r.per+' ':'')+(r.cls?'('+r.cls+') ':'')+'for absent teacher '+r.absent+' on '+r.date+'.'}));
  try{const cur=await db.doc('coord/alerts').get();const old2=cur.exists&&Array.isArray(cur.data().list)?cur.data().list:[];
   await db.doc('coord/alerts').set({list:[...old2,...al].slice(-60)});
   save.subSeen=Date.now()+1;save.alSeen=Date.now()+1;persist();
   E.msg('✔ Saved — notification sent to: '+[...new Set(al.flatMap(a=>a.names))].join(', '))}catch(e){E.msg('Saved, but the notification could not be sent')}
 };
})();

