const MT={db:null,admin:false,list:[],draft:{dept:'All Departments',title:'Department Meeting',date:'',from:'08:00',to:'09:00',place:'',agenda:''}};
const MDEPT=['All Departments','Islamic Studies','Arabic & Social Studies','English','Mathematics','Science','Applied Technology','Computer Science','Physical Education'];
(function buildMeet(){
 const r=$('meetRoot');r.innerHTML='<div class="mst" id="mtSt"></div><div class="mtg"><section class="card" id="mtForm"></section><section class="card"><h2 class="sec"><i>📅</i> Scheduled Meetings</h2><div class="mtl" id="mtList"></div></section></div>';
 const f=$('mtForm');f.innerHTML='<h2 class="sec"><i>👥</i> Organize a Meeting</h2>';
 const fld=(l,el)=>{const x=h('label','fld',l);x.append(el);return x};
 const inp=(k,ty)=>{const e=h('input');e.type=ty||'text';e.value=MT.draft[k];e.oninput=()=>MT.draft[k]=e.value;e.id='mt_'+k;return e};
 const sel=h('select');sel.id='mt_dept';MDEPT.forEach(d=>{const o=h('option','',d);o.value=d;sel.append(o)});sel.onchange=()=>MT.draft.dept=sel.value;
 const ag=h('textarea');ag.id='mt_agenda';ag.placeholder='Agenda / notes…';ag.oninput=()=>MT.draft.agenda=ag.value;
 const r2=h('div','r2');r2.append(fld('From',inp('from','time')),fld('To',inp('to','time')));
 const go=h('button','btn go','📣 Schedule Meeting');go.id='mt_go';go.onclick=addMeet;
 f.append(fld('Department',sel),fld('Meeting title',inp('title')),fld('Date',inp('date','date')),r2,fld('Location',inp('place')),fld('Agenda',ag),go);
})();
async function saveMeet(list){MT.list=list;try{if(MT.db)await MT.db.doc('coord/meetings').set({list,upd:Date.now()});else localStorage.setItem('tt_meet',JSON.stringify(list));$('mtSt').textContent='✔ Saved'+(MT.db?' and shared with everyone':' on this device only')}catch(e){$('mtSt').textContent='Could not save'+(e&&e.code?' ('+e.code+')':'')+' — only the coordinator/leaders can edit.'}drawMeet()}
function addMeet(){const d=MT.draft;if(!d.date||!d.place.trim()){$('mtSt').textContent='⚠ Please choose the date and enter the location.';return}
 const m={id:newId(),dept:d.dept,title:d.title.trim()||'Department Meeting',date:d.date,from:d.from,to:d.to,place:d.place.trim(),agenda:d.agenda.trim(),by:(MS.me&&MS.me.name)||'Coordinator',ts:Date.now()};
 saveMeet([...MT.list,m]);['date','place','agenda'].forEach(k=>{MT.draft[k]='';const e=$('mt_'+k);if(e)e.value=''})}
function drawMeet(){const L=$('mtList');if(!L)return;L.innerHTML='';
 const td=todayDubai(),mo=['JAN','FEB','MAR','APR','MAY','JUN','JUL','AUG','SEP','OCT','NOV','DEC'],wd=['SUN','MON','TUE','WED','THU','FRI','SAT'];
 const s=[...MT.list].sort((a,b)=>(a.date+a.from).localeCompare(b.date+b.from));
 $('mtForm').style.display=MT.admin?'':'none';
 if(!s.length){L.append(h('div','empty',MT.admin?'No meetings yet — fill in the form to schedule one.':'No meetings have been scheduled yet.'));return}
 s.forEach(m=>{const dt=new Date(m.date+'T00:00:00');const c=h('div','mc'+(m.date<td?' past':m.date===td?' today':''));
  const b=h('div','dt');b.append(h('span','',wd[dt.getDay()]),h('b','',dt.getDate()),h('small','',mo[dt.getMonth()]+' '+dt.getFullYear()));
  const x=h('div');x.append(h('span','dp',m.dept),h('h3','',m.title));
  const ln=h('div','ln');ln.append(h('span','','🕐 '+m.from+(m.to?' – '+m.to:'')),h('span','','📍 '+m.place));x.append(ln);
  if(m.agenda)x.append(h('div','ag',m.agenda));
  x.append(h('div','by',(m.date===td?'Today · ':'')+'Organized by '+m.by));
  c.append(b,x);
  if(MT.admin){const del=h('button','btn','✕ Cancel');del.onclick=()=>{if(confirm('Cancel this meeting?'))saveMeet(MT.list.filter(y=>y.id!==m.id))};c.append(del)}else c.append(h('span'));
  L.append(c)})}
(async function initMeet(){
 let db=null;try{if(window.claude&&claude.use)db=await claude.use('db')}catch(e){}
 MT.db=db;
 if(db){MT.admin=MS.admin;let n=0;const w=setInterval(()=>{MT.admin=MS.admin;drawMeet();if(++n>8)clearInterval(w)},500);
  $('mtSt').textContent=MS.admin?'Leader mode: you can schedule and cancel meetings; everyone sees them.':'View only — meetings are scheduled by the department leaders.';
  db.doc('coord/meetings').onSnapshot(s=>{MT.list=s.exists&&Array.isArray(s.data().list)?s.data().list:[];MT.admin=MS.admin;$('mtSt').textContent=MT.admin?'Leader mode: you can schedule and cancel meetings; everyone sees them.':'View only — meetings are scheduled by the department leaders.';drawMeet()},()=>{})}
 else{MT.admin=true;try{MT.list=JSON.parse(localStorage.getItem('tt_meet')||'[]')}catch(e){MT.list=[]}$('mtSt').textContent='Shared saving is not available here — meetings are saved on this device only.'}
 drawMeet();
})();



