(function(){const gs=$('gs'),gl=$('gsl'),gx=$('gsx');let items=[],ix=-1;
 const pick=it=>{Object.assign(F,{t:'',c:'',k:'',r:'',d:'',q:'',g:''});F.days.clear();$('fQ').value='';if(it.k==='t')F.t=it.v;else if(it.k==='c')F.c=it.v;else if(it.k==='k')F.k=it.v;else if(it.k==='r')F.r=it.v;showView('teachers');render();gl.hidden=true;gs.value=it.v;gx.style.display='block';setTimeout(()=>{const e=$('ti');e&&e.scrollIntoView({behavior:'smooth',block:'start'})},60)};
 function build(){const q=gs.value.trim().toLowerCase();gx.style.display=q?'block':'none';gl.innerHTML='';ix=-1;
  if(!q){gl.hidden=true;items=[];return}
  const grp=[['t','TEACHERS',names.filter(n=>n.toLowerCase().includes(q)||(LEAD[n]&&('leader قيادي '+LEAD[n].t+' '+LEAD[n].e).toLowerCase().includes(q))).map(n=>({k:'t',v:n,s:(LEAD[n]?'⭐ Leader · '+LEAD[n].t+' · ':'')+cnt(n)+' lessons'}))],
   ['c','CLASSES',uniq(ALL.map(l=>l.c)).filter(c=>c.toLowerCase().includes(q)&&(ROLE!=='student'||/^A\d\d/.test(c))).map(c=>({k:'c',v:c,s:ALL.filter(l=>l.c===c).length+' lessons'}))],
   ['k','COURSES',uniq(ALL.map(l=>l.k).filter(Boolean)).filter(c=>c.toLowerCase().includes(q)).map(c=>({k:'k',v:c,s:(n=>n+(n===1?' teacher':' teachers'))(new Set(ALL.filter(l=>l.k===c).map(l=>l.t)).size)}))],
   ['r','ROOMS',uniq(ALL.map(l=>l.r).filter(Boolean)).filter(c=>c.toLowerCase().includes(q)).map(c=>({k:'r',v:c,s:ALL.filter(l=>l.r===c).length+' lessons'}))]];
  items=[];grp.filter(g=>ROLE!=='student'||g[0]==='c').forEach(([k,h2,arr])=>{if(!arr.length)return;gl.append(h('div','gsh',h2));arr.slice(0,8).forEach(it=>{const e=h('div','gsi');e.append(h('span','',it.v),h('small','',it.s));e.onmousedown=ev=>{ev.preventDefault();pick(it)};gl.append(e);items.push([it,e])})});
  if(!items.length)gl.append(h('div','gsi',h('span','','No results')));gl.hidden=false}
 gs.oninput=build;gs.onfocus=build;gs.onblur=()=>setTimeout(()=>gl.hidden=true,120);
 gs.onkeydown=e=>{if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();if(!items.length)return;ix=(ix+(e.key==='ArrowDown'?1:-1)+items.length)%items.length;items.forEach(([_,el],i)=>el.classList.toggle('on',i===ix));items[ix][1].scrollIntoView({block:'nearest'})}else if(e.key==='Enter'){const it=items[ix<0?0:ix];if(it)pick(it[0])}else if(e.key==='Escape'){gl.hidden=true}};
 gx.onclick=()=>{gs.value='';build();gs.focus()}})();


