function nowD(){const o={};DFMT.formatToParts(new Date()).forEach(p=>o[p.type]=p.value);return{d:{Mon:0,Tue:1,Wed:2,Thu:3,Fri:4,Sat:5,Sun:6}[o.weekday],s:(+o.hour)*3600+(+o.minute)*60+(+o.second)}}
const ts=x=>{const [h,m]=x.trim().split(':').map(Number);return h*3600+m*60};
const fmt=s=>{s=Math.max(0,s);const h=Math.floor(s/3600),m=Math.floor(s%3600/60),r=s%60,z=n=>String(n).padStart(2,'0');return (h?h+':':'')+z(m)+':'+z(r)};
const hm=s=>Math.floor(s/3600)+':'+String(Math.floor(s%3600/60)).padStart(2,'0');
function sched(st,d){return (d===4?TX(st).f:TX(st).w).map(e=>{const [a,b]=e[1].split(' - ');return{k:e[0],a:ts(a),b:ts(b),br:e[0][0]==='b'}})}
function lblOf(it){return it.br?'Break':'Period '+it.k}
function tick(){
 const n=nowD(),L=$('bl'),T=$('bt'),P=$('bp'),N=$('bn'),box=$('tb');
 const tag=RM?' 🌙':'';
 if(n.d>4){L.textContent='Weekend'+tag;T.textContent='--:--';P.style.width='0';N.textContent='No school today (UAE time)';BELL.last=n.s;return}
 const sc=sched(BELL.st,n.d);
 if(BELL.last!==null&&n.s>BELL.last){
  const bs=[];sc.forEach(it=>{if(!it.br){bs.push({s:it.a,k:'start',m:'Started '+lblOf(it)});bs.push({s:it.b,k:'end',m:'Ended '+lblOf(it)})}});
  const hit=bs.filter(b=>b.s>BELL.last&&b.s<=n.s&&n.s-b.s<=10).sort((x,y)=>(y.k==='start')-(x.k==='start'))[0];
  if(hit){BELL.msg=hit.m;BELL.until=Date.now()+9000;if(BELL.on){ring(hit.k);bellToast(hit.m,hit.k)}}
 }
 BELL.last=n.s;
 const i=sc.findIndex(it=>n.s>=it.a&&n.s<it.b);
 let lab='',rem=0,pg=0,nx='';
 if(i>=0){const it=sc[i];lab=lblOf(it);rem=it.b-n.s;pg=(n.s-it.a)/(it.b-it.a)*100;const x=sc[i+1];nx=x?'Next: '+lblOf(x)+' Time '+hm(x.a):'last recorded period today'}
 else{const x=sc.find(it=>it.a>n.s);if(x){lab=n.s<sc[0].a?'Before the school day':'Break between periods';rem=x.a-n.s;nx='Next: '+lblOf(x)+' Time '+hm(x.a)}else{lab='All recorded periods have ended';nx=n.d===4?'Friday’s timetable in the file covers up to period 4 only':'School day ended'}}
 L.textContent=lab+tag;T.textContent=x2(rem,lab);P.style.width=pg+'%';
 const ringing=Date.now()<BELL.until;
 box.classList.toggle('ring',ringing);
 let tail=BELL.on&&BELL.mute?' — 🔇 sound muted':(BELL.on&&(!BELL.ctx||BELL.ctx.state!=='running')?' — 🔊 tap anywhere once to enable the bell sound':(!BELL.on?' — 🔕 bell is off':''));
 N.textContent=(ringing?'🔔 '+BELL.msg+' — ':'')+nx+tail;
}
function x2(rem,lab){return lab==='All recorded periods have ended'?'--:--':fmt(rem)}
bellUI();tick();setInterval(tick,1000);
const _r0=render;render=function(){_r0();fitBoard()};
if(window.ResizeObserver)new ResizeObserver(()=>fitBoard()).observe($('bw'));

