 const vb=document.querySelector('#v_teachers .vban');if(vb){const h2=vb.querySelector('h2'),pp=vb.querySelector('p');if(h2)h2.textContent='My Class Timetable';if(pp)pp.textContent='Lessons by class: subjects, teachers, rooms and timings'}
 const gsi=document.getElementById('gs')||document.querySelector('#sbar input');if(gsi)gsi.placeholder='Search for your class…';
